import "server-only";
/** Only normalized public product/movie images have bearer download URLs.
 * The token was generated by this server and persisted as object metadata during save;
 * no second metadata RPC is necessary. QR/branding media never use this helper. */
export function publicImageUrl(
  bucket: string,
  storagePath: string,
  token: string,
) {
  const emulator = process.env.FIREBASE_STORAGE_EMULATOR_HOST;
  const endpoint = emulator
    ? `http://${emulator}/v0`
    : "https://firebasestorage.googleapis.com/v0";
  return `${endpoint}/b/${encodeURIComponent(bucket)}/o/${encodeURIComponent(storagePath)}?alt=media&token=${encodeURIComponent(token)}`;
}
